<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Factories\HasFactory;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Foundation\Auth\User as Authenticatable;
use Illuminate\Notifications\Notifiable;
use Illuminate\Database\Eloquent\SoftDeletes;
class StaffMember extends Authenticatable { use HasFactory, Notifiable, SoftDeletes; protected $fillable=['uuid','staff_number','full_name','email','email_verified_at','whatsapp_number','whatsapp_verified_at','job_role','department','joined_on','employment_status','password','kyc_verified_at','kyc_verified_by_admin_id','bank_account_holder','bank_name','bank_branch','bank_account_number_encrypted','usdt_network','usdt_address_encrypted','payout_details_locked_at','employment_agreement_accepted_at','employment_agreement_version','termination_agreement_accepted_at','termination_agreement_version']; protected $hidden=['password','remember_token','bank_account_number_encrypted','usdt_address_encrypted']; protected function casts(): array { return ['password'=>'hashed','email_verified_at'=>'datetime','whatsapp_verified_at'=>'datetime','joined_on'=>'date','kyc_verified_at'=>'datetime','payout_details_locked_at'=>'datetime','employment_agreement_accepted_at'=>'datetime','termination_agreement_accepted_at'=>'datetime','bank_account_number_encrypted'=>'encrypted','usdt_address_encrypted'=>'encrypted']; } public function leaveRequests(): HasMany { return $this->hasMany(StaffLeaveRequest::class); } public function salaryPayments(): HasMany { return $this->hasMany(StaffSalaryPayment::class); } public function agreements(): HasMany { return $this->hasMany(StaffAgreement::class); } public function payoutChangeRequests(): HasMany { return $this->hasMany(StaffPayoutChangeRequest::class); } public function canLogin(): bool { return $this->employment_status==='ACTIVE' && $this->employment_agreement_accepted_at!==null && $this->deleted_at===null; } }
